<template><section class="material-preparation"><h2>企业级评测材料准备</h2><p>仅企业范围。项目输入不能提升为企业材料。预览、登记均不等于核准或评测通过。</p><p v-if="error" role="alert">{{ error }}</p>
<section v-if="pending"><h3>原登记请求待核查</h3><p>{{ pending.key }} · {{ pending.body.kind }} · {{ pending.body.source_version }}</p><pre>{{ JSON.stringify(pending.body,null,2) }}</pre><el-button :disabled="busy" @click="recover">查询原操作并固定回读</el-button><p v-if="lookupStatus">原操作：{{ lookupStatus }}。未找到不代表未发生；不会自动重试。</p><el-checkbox v-model="attested" :disabled="busy">我已核查完整原请求，明确按原key重放</el-checkbox><el-button :disabled="busy||!attested||!sameContext||lookupStatus!=='NOT_FOUND'" @click="send">显式重放原登记</el-button></section>
<template v-else>
<el-radio-group v-model="kind" :disabled="busy"><el-radio value="EXPECTED_ITEMS">1. 预期项目集</el-radio><el-radio value="SAMPLE_MANIFEST">2. 完整样本清单</el-radio><el-radio value="AUTHORIZED_USE_EVIDENCE">3. 授权用途见证</el-radio></el-radio-group>
<template v-if="kind==='EXPECTED_ITEMS'"><el-button v-if="inputRef" :disabled="busy" @click="useInput">使用上方真实输入回执</el-button><simulation-sample-editor :model-value="expected" label="预期项目集" :manifest="false" :disabled="busy"/></template>
<template v-else>
<div class="read-fixed"><el-form-item label="从已登记ExpectedItems读取真实样本（固定ARTIFACT ID）"><el-input v-model="expectedId" :disabled="busy"/></el-form-item><el-button :disabled="busy" @click="importExpected">读取并加入样本</el-button></div>
<el-button :disabled="busy||samples.length>=100" @click="samples.push(blank())">添加已有业务样本</el-button><simulation-sample-editor v-for="(sample,i) in samples" :key="i" :model-value="sample" :label="'样本 '+(i+1)" :manifest="true" :disabled="busy"/><el-button v-if="samples.length" :disabled="busy" @click="samples.pop()">移除最后一个样本</el-button>
</template>
<template v-if="kind==='AUTHORIZED_USE_EVIDENCE'"><evaluation-basis-field v-model="dataset" label="企业数据集固定版本" kind="artifact" :disabled="busy"/><el-form-item label="已登记完整样本清单ARTIFACT ID"><el-input v-model="manifestId" :disabled="busy"/></el-form-item><el-button :disabled="busy" @click="importManifest">读取清单并带入完整样本</el-button><p>固定清单引用：{{ manifestRef.version_id }} · {{ manifestRef.content_sha256 }}</p><p>审批witness由服务端根据当前权利重建。此页不编辑许可证据、私有证据ID或witness。</p></template>
<el-button type="primary" :disabled="busy" @click="preview">核验引用并生成canonical预览</el-button>
<section v-if="previewValue"><h3>待登记的规范文档</h3><router-link to="/sources/uploads">企业资料上传入口</router-link><p>SHA-256：{{ previewValue.document_sha256 }}</p><el-button :disabled="busy" @click="download">下载原样canonical TXT</el-button><el-form-item label="选择真实处理项目（资料归属仍为企业）"><el-input v-if="busy" :model-value="uploadProject" disabled/><project-scope-select v-else v-model="uploadProject"/></el-form-item><router-link v-if="uploadProjectValid" :to="{path:'/projects/'+uploadProject+'/uploads',query:{ownership:'ENTERPRISE'}}">打开企业资料上传</router-link><p>所选项目用于上传处理，资料归属企业。</p><p>上传本文件，不重新排版或添加换行。完成企业来源核准及SIMULATION_EVALUATION权利审核后，返回选择固定来源。服务端不会自动上传、审批或改变许可。</p><el-collapse><el-collapse-item title="完整服务器规范文档"><pre>{{ previewValue.canonical_json }}</pre></el-collapse-item></el-collapse>
<el-button :disabled="busy" @click="loadSources()">读取已核准企业来源</el-button><el-button v-if="sourcePage?.next_after" :disabled="busy" @click="loadSources(sourcePage.next_after)">下一页</el-button><el-select v-model="sourceId" :disabled="busy" @change="chooseSource"><el-option v-for="s in sourcePage?.items??[]" :key="s.source_version" :value="s.source_version" :label="s.title+' · '+s.source_version"/></el-select><p v-if="source">{{ source.title }} · 原件SHA {{ source.original_sha256 }} · 权利 {{ source.rights_revision }} / {{ source.rights_status }} / {{ source.rights_purpose }}</p><el-checkbox v-model="attested" :disabled="busy">我已上传规范原件并核查真实来源与当前权利，明确登记此材料</el-checkbox><el-button type="primary" :disabled="busy||!attested||!source" @click="register">登记真实来源为材料ARTIFACT</el-button></section>
</template>
<section v-if="result"><h3>已登记材料回执（非核准）</h3><p>{{ result.kind }} · {{ result.artifact.version_id }}</p><p>source {{ result.source_version }} · rights {{ result.rights_revision }}</p><p>操作 {{ result.operation_id }} · {{ result.created_at }}</p><el-input type="textarea" readonly :model-value="JSON.stringify(result.artifact)" aria-label="可复制的材料固定引用"/><p>registered=true；approved=false；production_eligible=false。</p></section>
</section></template>
<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import useUserStore from '@/store/modules/user'
import {schemaIssues} from '@/api/medical/protocol'
import type {Basis,MedicalSession} from '@/api/medical/protocol'
import type {EvaluationSample} from '@/api/medical/evaluation-domain'
import {sourceDigest} from '@/api/medical/content-digest'
import {readSourceCatalogue,readSourceGovernance} from '@/api/medical/source-governance'
import type {SourceCataloguePage,SourceGovernanceView} from '@/api/medical/source-governance'
import {materialIssues,previewMaterial,registerMaterial,readMaterial,recoverMaterial,retainMaterial,restoreMaterial,forgetMaterial,verifyMaterialPending,canonicalPreparation} from '@/api/medical/simulation-evaluation-preparation'
import type {PreparationKind,PreparationPreview,RegisteredPreparation,PendingMaterial} from '@/api/medical/simulation-evaluation-preparation'
import EvaluationBasisField from './evaluation-basis-field.vue'
import SimulationSampleEditor from './simulation-sample-editor.vue'
import ProjectScopeSelect from '@/components/Medical/ProjectScopeSelect.vue'
const props=defineProps<{inputRef?:Basis|undefined}>(),user=useUserStore()
const blank=():EvaluationSample=>({sample_id:'',source_family:'',split:'DEVELOPMENT',document_type:'',evidence_class:'SIMULATION',input_ref:{version_id:'',content_sha256:''},expected_ref:{version_id:'',content_sha256:''},expectations:[]})
const kind=ref<PreparationKind>('EXPECTED_ITEMS'),expected=ref(blank()),samples=ref<EvaluationSample[]>([]),dataset=ref<Basis>({version_id:'',content_sha256:''}),manifestRef=ref<Basis>({version_id:'',content_sha256:''})
const uploadProject=ref('')
const uploadProjectValid=computed(()=>uploadProject.value!==''&&schemaIssues('urn:medical:templates:1.0.0#/$defs/Id',uploadProject.value).length===0)
const expectedId=ref(''),manifestId=ref(''),sourceId=ref(''),sourcePage=ref<SourceCataloguePage|null>(null),source=ref<SourceGovernanceView|null>(null),previewValue=ref<PreparationPreview|null>(null)
const pending=ref<PendingMaterial|null>(null),result=ref<RegisteredPreparation|null>(null),lookupStatus=ref(''),error=ref(''),attested=ref(false),loading=ref(false)
const busy=computed(()=>loading.value||user.medicalWriting),sameContext=computed(()=>!!pending.value&&canonicalPreparation(pending.value.context)===canonicalPreparation(user.medicalSession?.current_context))
let generation=0,controller=new AbortController(),active=true,ownsWrite=false,url:string|null=null
function live(g:number,s:unknown){return active&&g===generation&&s===user.medicalSession&&!document.hidden}
function invalidatePreview(){previewValue.value=null;source.value=null;sourceId.value='';attested.value=false;if(url){URL.revokeObjectURL(url);url=null}}
watch([kind,expected,samples,dataset,manifestRef],invalidatePreview,{deep:true,flush:'sync'})
function useInput(){if(props.inputRef&&!busy.value)expected.value.input_ref={...props.inputRef}}
function specification(){if(kind.value==='EXPECTED_ITEMS'){const {sample_id,source_family,document_type,input_ref,expectations}=expected.value;return {schema_version:'1.0.0',sample_id,source_family,document_type,input_ref,expectations}}if(kind.value==='SAMPLE_MANIFEST')return JSON.parse(JSON.stringify(samples.value));return {schema_version:'1.0.0',dataset:dataset.value,sample_manifest_artifact:manifestRef.value,samples:samples.value}}
async function run<T>(work:(s:NonNullable<typeof user.medicalSession>,signal:AbortSignal)=>Promise<T>,apply:(v:T)=>void){const s=user.medicalSession;if(!s?.current_context||busy.value||document.hidden)return;const g=generation;loading.value=true;error.value='';try{const v=await work(s,controller.signal);if(live(g,s))apply(v)}catch(e){if(live(g,s))error.value=e instanceof Error?e.message:'请求失败'}finally{if(live(g,s))loading.value=false}}
function preview(){if(busy.value||pending.value)return;const spec=specification(),issues=materialIssues(kind.value,spec);if(issues.length){error.value=issues.join('\n');return}if(new TextEncoder().encode(JSON.stringify(spec)).length>1000000){error.value='文档超出准备容量';return}const k=kind.value;return run((s,signal)=>previewMaterial(s,k,spec,signal),v=>{previewValue.value=v;source.value=null;attested.value=false})}
function validId(id:string){if(schemaIssues('urn:medical:templates:1.0.0#/$defs/Id',id).length){error.value='请填写真实规范ARTIFACT标识';return false}return true}
function importExpected(){if(!validId(expectedId.value))return;return run((s,signal)=>readMaterial(s,expectedId.value,signal),v=>{if(v.receipt.kind!=='EXPECTED_ITEMS'){error.value='此固定制品不是ExpectedItems';return}const d=v.document as Omit<EvaluationSample,'split'|'evidence_class'|'expected_ref'>&{schema_version:string};samples.value.push({sample_id:d.sample_id,source_family:d.source_family,document_type:d.document_type,input_ref:d.input_ref,expectations:d.expectations,split:'DEVELOPMENT',evidence_class:'SIMULATION',expected_ref:v.receipt.artifact})})}
function importManifest(){if(!validId(manifestId.value))return;return run((s,signal)=>readMaterial(s,manifestId.value,signal),v=>{if(v.receipt.kind!=='SAMPLE_MANIFEST'){error.value='此固定制品不是完整样本清单';return}samples.value=v.document as EvaluationSample[];manifestRef.value=v.receipt.artifact})}
function loadSources(after?:string){return run((s,signal)=>readSourceCatalogue(s,{limit:25,ownership:'ENTERPRISE',approval_status:'APPROVED',lifecycle:'ACTIVE',...(after?{after}:{})},signal),v=>{sourcePage.value=v})}
function chooseSource(){source.value=null;attested.value=false;return run((s,signal)=>readSourceGovernance(s,sourceId.value,signal),v=>{source.value=v})}
function download(){if(!previewValue.value||busy.value)return;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([previewValue.value.canonical_json],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=previewValue.value.kind.toLowerCase()+'.txt';a.click()}
async function register(){const s=user.medicalSession,v=previewValue.value,original=source.value;if(!s?.current_context||!v||!original||busy.value||pending.value||!attested.value)return;if(!s.action_summary.some((item:MedicalSession['action_summary'][number])=>item.action==='artifact.register')){error.value='当前没有材料制品登记权限';return}if(original.ownership!=='ENTERPRISE'||original.owner_project_id!==null||original.original_sha256!==v.document_sha256){error.value='须选择原字节摘要与规范预览完全相同的企业来源';return}const g=generation;loading.value=true;try{const value={actor:s.user.user_id,context:{...s.current_context},key:crypto.randomUUID(),body:{schema_version:'1.0.0' as const,project_id:null,kind:v.kind,source_version:original.source_version,rights_revision:original.rights_revision,document_sha256:v.document_sha256}};const digest=await sourceDigest(value);if(!live(g,s))return;pending.value={...value,digest};retainMaterial(s,pending.value)}finally{if(live(g,s))loading.value=false}await send()}
async function send(){const s=user.medicalSession,p=pending.value;if(!s?.current_context||!p||busy.value||!attested.value||!sameContext.value||document.hidden)return;const g=generation;ownsWrite=true;user.medicalWriting=true;error.value='';try{const value=await registerMaterial(s,p,controller.signal);if(live(g,s)){result.value=value;pending.value=null;forgetMaterial(s);attested.value=false;invalidatePreview()}}catch(e){if(live(g,s))error.value=e instanceof Error?e.message:'结果未知，保留原请求'}finally{if(ownsWrite){ownsWrite=false;user.medicalWriting=false}}}
function recover(){const p=pending.value;if(!p)return;return run((s,signal)=>recoverMaterial(s,p,signal),v=>{lookupStatus.value=v.status;if(v.value){result.value=v.value.receipt;pending.value=null;forgetMaterial(user.medicalSession!);attested.value=false}})}
function clear(){generation++;controller.abort();controller=new AbortController();invalidatePreview();kind.value='EXPECTED_ITEMS';expected.value=blank();samples.value=[];dataset.value={version_id:'',content_sha256:''};manifestRef.value={version_id:'',content_sha256:''};expectedId.value='';manifestId.value='';uploadProject.value='';sourcePage.value=null;pending.value=null;result.value=null;lookupStatus.value='';error.value='';loading.value=false}
async function restore(){clear();const s=user.medicalSession;if(!s?.current_context||document.hidden)return;const g=generation;try{const p=restoreMaterial(s);if(p){await verifyMaterialPending(s,p,false);if(live(g,s))pending.value=p}}catch(e){if(live(g,s))error.value=e instanceof Error?e.message:'恢复失败'}}
watch(()=>[user.medicalSession,canonicalPreparation(user.medicalSession?.current_context??null)],restore,{immediate:true,flush:'sync'})
function visibility(){void restore()}function unload(e:BeforeUnloadEvent){if(pending.value||ownsWrite){e.preventDefault();e.returnValue=''}}
document.addEventListener('visibilitychange',visibility);window.addEventListener('beforeunload',unload)
onBeforeUnmount(()=>{active=false;clear();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('beforeunload',unload)})
</script>
<style scoped>.material-preparation{border-top:2px solid #dce3ec;padding:24px 0;margin-top:32px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto}.el-button{margin:8px}.el-select{width:100%}p{overflow-wrap:anywhere;line-height:1.6}</style>
